#include <cctype>
#include <map>
#include <set>
#include <string>
#include <utility>
#include <vector>

struct Module
{
    std::vector<std::pair<std::string, std::string>> imports;
    std::set<std::string> exports;
};

static std::string lower(std::string s)
{
    for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return s;
}

using Disk = std::map<std::string, Module>;

static const Disk::value_type* find(const Disk& disk, const std::string& name)
{
    const std::string key{ lower(name) };
    for (const auto& entry : disk) if (lower(entry.first) == key) return &entry;
    return nullptr;
}

static void visit(const Disk& disk, const Disk::value_type* module, std::set<std::string>& started, std::vector<const Disk::value_type*>& order)
{
    if (!started.insert(lower(module->first)).second) return;
    for (const auto& import : module->second.imports)
        if (const auto* dependency{ find(disk, import.first) }) visit(disk, dependency, started, order);
    order.push_back(module);
}

std::vector<std::string> loaderReport(const std::map<std::string, Module>& onDisk, const std::string& program)
{
    const auto* root{ find(onDisk, program) };
    if (!root) return { program + " was not found." };
    std::set<std::string> started;
    std::vector<const Disk::value_type*> order;
    visit(onDisk, root, started, order);
    for (const auto* module : order)
    {
        for (const auto& [dll, function] : module->second.imports)
        {
            const auto* target{ find(onDisk, dll) };
            if (!target) return { "The code execution cannot proceed because " + dll + " was not found." };
            if (!target->second.exports.count(function)) return { "The procedure entry point " + function + " could not be located in the dynamic link library " + dll + "." };
        }
    }
    std::vector<std::string> report;
    for (const auto* module : order) report.push_back("load " + module->first);
    report.push_back("start " + root->first);
    return report;
}

