using Lines = std::vector<std::string>;
std::map<std::string, Module> sampleDisk()
{
    std::map<std::string, Module> disk;
    disk["game.exe"] = Module{ { {"audio.dll", "play"}, {"KERNEL32.dll", "WriteFile"} }, {} };
    disk["audio.dll"] = Module{ { {"kernel32.dll", "CreateFileW"} }, { "play", "stop" } };
    disk["kernel32.dll"] = Module{ {}, { "WriteFile", "CreateFileW" } };
    return disk;
}
TEST("the example starts") { CHECK_EQ(loaderReport(sampleDisk(), "game.exe"), (Lines{ "load kernel32.dll", "load audio.dll", "load game.exe", "start game.exe" })); }
TEST("missing program") { CHECK_EQ(loaderReport(sampleDisk(), "editor.exe"), (Lines{ "editor.exe was not found." })); }
TEST("missing DLL") {
    auto disk = sampleDisk(); disk.erase("audio.dll");
    CHECK_EQ(loaderReport(disk, "game.exe"), (Lines{ "The code execution cannot proceed because audio.dll was not found." }));
}
TEST("missing entry point in a dependency is found first") {
    auto disk = sampleDisk(); disk["kernel32.dll"].exports = { "WriteFile" };
    CHECK_EQ(loaderReport(disk, "game.exe"), (Lines{ "The procedure entry point CreateFileW could not be located in the dynamic link library kernel32.dll." }));
}
TEST("program name case") { CHECK_EQ(loaderReport(sampleDisk(), "GAME.EXE").back(), std::string("start game.exe")); }
TEST("a program with no imports") { std::map<std::string, Module> d; d["tool.exe"] = Module{}; CHECK_EQ(loaderReport(d, "tool.exe"), (Lines{ "load tool.exe", "start tool.exe" })); }

